 (MG,'toss','ใส่ผักแล้วผัดเร็วๆ','น้ำมันกระเด็นตอนเทผัก','เทห่างตัว ให้ผักไหลลงจากขอบกระทะฝั่งที่ห่างตัว ถ้าโดนผิว ให้ทำตามข้อ "โดนน้ำมันหรือกระทะลวก"',ALL,S),
 (MG,'toss','ใส่ผักแล้วผัดเร็วๆ','ผักเยอะจนผัดไม่ไหว','ใช้ตะหลิวกับทัพพีช่วยพลิกจากล่างขึ้นบน หรือแบ่งผัดสองรอบ',ALL,G),
 (MG,'toss','ใส่ผักแล้วผัดเร็วๆ','ผัดนานแค่ไหน','ราว 1 นาที พอใบเริ่มสลดและก้านยังเขียวกรอบก็ปิดไฟ',ALL,G),
 (MG,'off','ปิดไฟ ตักขึ้นทันที','ผักเหี่ยวและสีคล้ำ','ผัดนานหรือทิ้งในกระทะร้อนนานไป ยังกินได้ปกติ ครั้งหน้าตักขึ้นทันทีที่ปิดไฟ',ALL,G),
 (MG,'off','ปิดไฟ ตักขึ้นทันที','มีน้ำในจานเยอะ','ผักเปียกหรือไฟไม่แรงพอ ครั้งหน้าสะเด็ดน้ำให้หมาดและรอน้ำมันร้อนกว่านี้',ALL,G),
 (MG,'plate','จัดจาน','เก็บไว้กินทีหลังได้ไหม','ได้ถ้าเข้าตู้เย็นภายใน 2 ชั่วโมง แต่ผักจะเหี่ยวและเสียความกรอบ ผัดใหม่อร่อยกว่า',ALL,S),
 (MG,'plate','จัดจาน','ใส่หมูกรอบหรือกุ้งด้วยได้ไหม','ได้ ใส่หมูกรอบตอนท้ายพอคลุก ส่วนกุ้งผัดให้สุกก่อนแล้วค่อยใส่ผัก',ALL,G),
 # ต้มยำกุ้ง
 (TY,'fridge','หยิบของจากตู้เย็น','กุ้งแช่แข็ง ละลายยังไง','แช่ทั้งถุงที่ปิดสนิทในน้ำเย็นจนนิ่ม หรือย้ายลงช่องธรรมดาตั้งแต่คืนก่อน อย่าใช้น้ำร้อน',ALL,S),
 (TY,'fridge','หยิบของจากตู้เย็น','กุ้งมีกลิ่นเหม็นหรือหัวดำ','ไม่ควรใช้ กุ้งสดควรตัวใสเป็นเงาและกลิ่นอ่อนๆ',ALL,S),
 (TY,'fridge','หยิบของจากตู้เย็น','ไม่มีเห็ดฟาง ใช้อะไรแทน','เห็ดนางฟ้าหรือเห็ดหอมสดใช้ได้ หรือใส่มะเขือเทศผ่าซีกแทน',ALL,G),
 (TY,'shrimp_prep','เตรียมกุ้ง','ต้องเอาเส้นดำออกไหม','ควรเอาออก มีทรายและกลิ่นคาว ใช้ไม้จิ้มฟันเกี่ยวตรงข้อที่สองจากหัวแล้วดึงออกได้โดยไม่ต้องผ่าหลัง',ALL,G),
 (TY,'shrimp_prep','เตรียมกุ้ง','ไว้เปลือกหรือปอกดี','ไว้เปลือกน้ำซุปจะหวานกว่าแต่กินยาก ปอกแล้วกินง่าย ถ้าปอก ต้มเปลือกกับหัวในน้ำก่อน 5 นาทีแล้วตักทิ้ง จะได้ความหวานเหมือนกัน',ALL,G),
 (TY,'herbs','เตรียมสมุนไพร','ใช้เครื่องต้มยำแบบแพ็กได้ไหม','ได้ เป็นชุดตะไคร้ ข่า ใบมะกรูดพร้อมใช้ ทุบตะไคร้อีกนิดก่อนใส่',ALL,G),
 (TY,'herbs','เตรียมสมุนไพร','ข่าแข็งมาก หั่นไม่เข้า','ใช้มีดหนักกดลงตรงๆ อย่าเลื่อยไปมา และงอนิ้วมือที่จับข่าไว้ให้พ้นใบมีด',ALL,S),
 (TY,'boil','ต้มน้ำ','ใช้น้ำซุปแทนน้ำเปล่าได้ไหม','ได้ รสจะกลมขึ้น ลดน้ำปลาลงครึ่งหนึ่งก่อนแล้วชิม',ALL,G),
 (TY,'boil','ต้มน้ำ','ใช้ก้อนซุปต้มยำได้ไหม','ได้ ลดน้ำปลาลงมาก เพราะก้อนซุปเค็มอยู่แล้ว ชิมก่อนเติม',ALL,G),
 (TY,'herbs_in','ต้มสมุนไพร','ต้มสมุนไพรนานไปได้ไหม','ต้มนานเกิน 10 นาที ข่าจะเริ่มขมฝาด 3 ถึง 5 นาทีก็พอ',ALL,G),
 (TY,'herbs_in','ต้มสมุนไพร','มีฟองลอยขึ้นมา','ใช้ทัพพีตักฟองทิ้ง น้ำซุปจะใสขึ้น',ALL,G),
 (TY,'mushroom','ใส่เห็ด','เห็ดต้องล้างไหม','ล้างเร็วๆ ใต้น้ำไหล อย่าแช่น้ำนาน เห็ดจะอมน้ำ',ALL,G),
 (TY,'mushroom','ใส่เห็ด','เห็ดกลิ่นแรงหรือเป็นเมือก','ไม่ควรใช้ เห็ดสดควรแน่นและกลิ่นอ่อน',ALL,S),
 (TY,'shrimp','ใส่กุ้ง','รู้ได้ยังไงว่ากุ้งสุก','เนื้อเปลี่ยนจากใสเป็นขาวขุ่น เปลือกเป็นสีส้มทั้งตัว ใช้เวลาราว 2 นาที',ALL,S),
 (TY,'shrimp','ใส่กุ้ง','กุ้งเหนียว หดเล็ก','ต้มนานไป ครั้งหน้าใส่กุ้งท้ายสุดและปิดไฟทันทีที่สุก',ALL,G),
 (TY,'off','ปิดไฟ','ทำไมต้องปิดไฟก่อนปรุง','มะนาวโดนเดือดนานจะขมและกลิ่นหาย ความร้อนที่เหลือพอให้น้ำปลาละลาย',ALL,G),
 (TY,'off','ปิดไฟ','ยกหม้อร้อนยังไงให้ปลอดภัย','ใช้ผ้าจับหม้อหรือถุงมือกันร้อนสองมือ และหันด้ามหม้อเข้าด้านในเตา',ALL,S),
 (TY,'season','ปรุงรส','เปรี้ยวไป','เติมน้ำปลาอีกนิดกับน้ำตาลหยิบมือ หรือเติมน้ำร้อนอีกครึ่งถ้วย',ALL,G),
 (TY,'season','ปรุงรส','เค็มไป','เติมน้ำร้อนครึ่งถ้วยแล้วบีบมะนาวเพิ่มนิดหน่อย ชิมใหม่',ALL,G),
 (TY,'season','ปรุงรส','น้ำข้นแล้วนมเป็นเม็ดๆ','น้ำยังร้อนจัดหรือมะนาวลงก่อนนม ครั้งหน้าใส่นมก่อนแล้วค่อยบีบมะนาว ยังกินได้ปกติ','น้ำซุป: น้ำข้น',G),
 (TY,'plate','ตักใส่ชาม','ต้องกินตะไคร้กับข่าไหม','ไม่ต้อง ใส่ไว้ให้หอม เขี่ยออกได้',ALL,G),
 (TY,'plate','ตักใส่ชาม','เก็บไว้กินพรุ่งนี้ได้ไหม','ได้ถ้าเข้าตู้เย็นภายใน 2 ชั่วโมง อุ่นให้เดือดก่อนกิน แต่กุ้งจะเหนียวและน้ำจะเปรี้ยวน้อยลง บีบมะนาวเพิ่มตอนอุ่น',ALL,S),
 # แกงเขียวหวาน
 (GC,'fridge','หยิบของจากตู้เย็น','ใช้พริกแกงสำเร็จได้ไหม','ได้ และเหมาะกับมือใหม่ รสของแต่ละยี่ห้อต่างกัน ใส่น้อยก่อนแล้วชิม',ALL,G),
 (GC,'fridge','หยิบของจากตู้เย็น','กะทิกล่องเปิดแล้วเก็บได้นานไหม','เทใส่ภาชนะปิดฝาเก็บตู้เย็น และใช้ภายในไม่กี่วัน ถ้ามีกลิ่นเปรี้ยวให้ทิ้ง',ALL,S),
 (GC,'chicken_prep','หั่นไก่','ต้องล้างไก่ก่อนหั่นไหม','ไม่ต้อง การล้างไก่ดิบทำให้น้ำกระเด็นพาเชื้อไปทั่วซิงก์ ความร้อนตอนต้มจะฆ่าเชื้อเอง',ALL,S),
 (GC,'chicken_prep','หั่นไก่','หั่นไก่แล้วใช้เขียงต่อได้ไหม','ล้างเขียง มีด และมือด้วยน้ำยาล้างจานก่อนไปจับผัก หรือหั่นผักก่อนแล้วค่อยหั่นไก่',ALL,S),
 (GC,'veg','เตรียมผัก','ไม่มีมะเขือเปราะ','ใช้มะเขือยาว หน่อไม้ต้ม หรือฟักทองแทนได้',ALL,G),
 (GC,'veg','เตรียมผัก','มะเขือดำแล้ว','ยังใช้ได้ปกติ แค่สีไม่สวย ครั้งหน้าผ่าแล้วแช่น้ำเกลือทันที',ALL,G),
 (GC,'on','เปิดเตา','ใช้หม้อหรือกระทะดี','หม้อก้นหนาดีที่สุด กะทิไม่ไหม้ติดก้นง่าย กระทะก็ใช้ได้ถ้าคนบ่อย',ALL,G),
 (GC,'on','เปิดเตา','ใช้เตาไฟฟ้าได้ไหม','ได้ ใช้ระดับกลาง เตาไฟฟ้าร้อนช้า ให้เปิดรอก่อนสักครู่',ALL,G),
 (GC,'crack','ผัดพริกแกงกับกะทิ','กะทิไม่ยอมแตกมัน','ผัดต่อด้วยไฟกลาง กะทิกล่องบางยี่ห้อแตกมันยาก ถ้าเกิน 5 นาทีแล้วยังไม่แตก ใส่น้ำมันพืช 1 ช้อนโต๊ะช่วยได้',ALL,G),
 (GC,'crack','ผัดพริกแกงกับกะทิ','พริกแกงติดก้นหม้อ จะไหม้','หรี่ไฟลง คนตลอดและขูดก้นหม้อ ถ้าแห้งเกินเติมกะทิอีก 2 ช้อนโต๊ะ',ALL,G),
 (GC,'crack','ผัดพริกแกงกับกะทิ','ไอพริกแกงแสบจมูก','เป็นปกติของพริกที่โดนความร้อน เปิดพัดลมดูดควันหรือหน้าต่าง และหันหน้าออกจากหม้อ',ALL,G),
 (GC,'chicken','ใส่ไก่','ใช้อกไก่ ต้องทำต่างไหม','ผัดแค่พอผิวขาว แล้วเคี่ยวไม่นานเกินไป อกไก่สุกนานจะแห้งและแข็ง','เนื้อไก่: อก',G),
 (GC,'chicken','ใส่ไก่','ใช้หมูหรือลูกชิ้นแทนได้ไหม','ได้ หมูหั่นบางใส่ตอนนี้เหมือนไก่ ลูกชิ้นใส่ตอนเคี่ยวเพราะสุกอยู่แล้ว',ALL,G),
 (GC,'coconut','เติมกะทิที่เหลือ','แกงข้นเกินไป','เติมน้ำทีละ ¼ ถ้วย แล้วชิมรสใหม่หลังเดือด',ALL,G),
 (GC,'coconut','เติมกะทิที่เหลือ','แกงใสเกินไป','เคี่ยวต่ออีกครู่โดยไม่ปิดฝาให้น้ำงวด หรือเติมกะทิอีกนิด',ALL,G),
 (GC,'simmer','ใส่มะเขือแล้วเคี่ยว','รู้ได้ยังไงว่าไก่สุก','ผ่าชิ้นใหญ่สุดดู ไม่เหลือสีชมพูและน้ำใส ถ้ามีเทอร์โมมิเตอร์ ให้ได้อย่างน้อย 74°C',ALL,S),
 (GC,'simmer','ใส่มะเขือแล้วเคี่ยว','มะเขือพวงขมไป','ใส่น้อยลงครั้งหน้า หรือบุบให้แตกก่อนใส่จะขมน้อยกว่า',ALL,G),
 (GC,'simmer','ใส่มะเขือแล้วเคี่ยว','ต้องปิดฝาไหม','ไม่ต้อง เคี่ยวเปิดฝาจะคุมความข้นได้ง่ายกว่า และกะทิไม่ล้นหม้อ',ALL,G),
 (GC,'season','ปรุงรส','หวานไป','เติมน้ำปลาอีกครึ่งช้อนชาแล้วชิม ความเค็มช่วยกลบหวาน',ALL,G),
 (GC,'season','ปรุงรส','เผ็ดไป','เติมกะทิอีกนิดแล้วเคี่ยวต่อ กะทิช่วยลดความเผ็ด',ALL,G),
 (GC,'basil','ใส่โหระพา ปิดไฟ','ไม่มีโหระพา','ใช้ใบกะเพราได้ กลิ่นต่างไปแต่ยังเข้ากัน หรือข้ามไป',ALL,G),
 (GC,'basil','ใส่โหระพา ปิดไฟ','ราดหัวกะทิด้านบนด้วยได้ไหม','ได้ เหลือกะทิไว้ 1 ถึง 2 ช้อนโต๊ะ ราดหลังปิดไฟให้หน้าแกงขาวสวย',ALL,G),
 (GC,'plate','ตักใส่ชาม','เก็บแกงที่เหลือยังไง','รอให้หายร้อนแล้วเข้าตู้เย็นภายใน 2 ชั่วโมง กินภายใน 3 ถึง 4 วัน อุ่นให้เดือดก่อนกิน',ALL,S),
 (GC,'plate','ตักใส่ชาม','กินกับข้าวหรือขนมจีนดี','ได้ทั้งคู่ ขนมจีนต้องแกงน้ำเยอะกว่า เติมน้ำอีก ½ ถ้วยตอนเติมกะทิ',ALL,G),
